const e = $json;
const attendees = Array.isArray(e.attendees) ? e.attendees.map(function (a) { return a.email; }).filter(Boolean) : [];
const start = (e.start && (e.start.dateTime || e.start.date)) || '';
return { id: e.id || '', title: e.summary || 'Untitled meeting', description: e.description || '', start: start, attendees: attendees.join(', '), attendeeCount: attendees.length, link: e.htmlLink || '' };

parameters.text:
=You are an executive assistant. Write a short, practical prep note for the meeting below, to be read in under a minute. Include: a one-line purpose, 3 suggested talking points or questions, and 1 thing to prepare or bring. Keep it concrete and skip filler. If there is little information, infer sensibly from the title and attendees.

Meeting: {{ $json.title }}
When: {{ $json.start }}
Attendees: {{ $json.attendees }}
Notes: {{ $json.description }}

parameters.jsCode:
const preps = $input.all();
if (preps.length === 0) { return [{ json: { hasMeetings: false, count: 0, body: 'You have no meetings today. Enjoy the focus time!' } }]; }
const meetings = $('Shape Meetings').all();
const pretty = preps.map(function (p, idx) {
  const m = (meetings[idx] && meetings[idx].json) || {};
  return '=== ' + (m.title || 'Meeting') + ' (' + (m.start || '') + ') ===\n' + (p.json.text || '');
}).join('\n\n');
return [{ json: { hasMeetings: true, count: preps.length, body: 'Your meeting prep for today (' + preps.length + ' meetings):\n\n' + pretty } }];
